contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    // params: minSum to configure contract, dep to deposit, col to attempt collect
    function run(uint minSum, uint dep, uint col) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep) + (0)); require(dep <= 1000000000000000000000000000000);
        require(address(this).balance >= dep);

        // initialize contract (must be done before Initialized() call)
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(0)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        // record recorded balance and on-chain balance before any deposit
        uint beforeRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeOnChain = address(this).balance;

        // perform a deposit (may revert if overflow, but we're prepared)
        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;

        // snapshot after deposit
        uint afterRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterOnChain = address(this).balance;

        // try Collect and record whether it reverted
        bool reverted;
        c.Collect{value:0}(col); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint finalRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint finalOnChain = address(this).balance;

        // Assert general invariant:
        // 1) Collect never increases the recorded balance.
        // 2) If Collect succeeds then the test contract's on-chain balance does not decrease (Collect should only send Ether to the caller, not take from it).
        assert(finalRecorded <= afterRecorded && (reverted || finalOnChain >= afterOnChain));
    }

    // allow receiving ETH if Collect sends Ether to this contract
    receive() external payable {}
}

