// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 minSum, uint256 dep, uint256 col) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(address(0)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 beforeRecorded;
        try c.balances(address(this)) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        uint beforeOnChain = address(this).balance;
        try c.Deposit{value: dep}() {} catch { return; }
        uint256 afterRecorded;
        try c.balances(address(this)) returns (uint256 __r) { afterRecorded = __r; } catch { return; }
        uint afterOnChain = address(this).balance;
        bool reverted;
        try c.Collect{value:0}(col) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 finalRecorded;
        try c.balances(address(this)) returns (uint256 __r) { finalRecorded = __r; } catch { return; }
        uint finalOnChain = address(this).balance;
        assertTrue(finalRecorded <= afterRecorded && (reverted || finalOnChain >= afterOnChain));
    }

    function testFuzz_run(uint256 minSum, uint256 dep, uint256 col) public {
        _run(minSum, dep, col);
    }

    receive() external payable {}
}
